/**
 * @brief Dynamically updates timer period and restarts DMA for the active waveform.
 * This handles the variable sample sizes and frequencies.
 */
 void Configure_Audio_Output(void) {
 uint32_t sample_buffer_size;
 float output_freq_signal;
 if (waveform_selector>= 3) { // AUDIO
 sample_buffer_size = NS_INSTRUMENT;
 if (waveform_selector== 3) {
 output_freq_signal = F_SIGNAL_PIANO;
 }
 else if (waveform_selector== 4) {output_freq_signal = F_SIGNAL_GUITAR;
 }
 else {output_freq_signal = F_SIGNAL_DRUM;}
 }
 else { // waveforms
 sample_buffer_size = NS;
 output_freq_signal = F_SIGNAL;
 }
 // Recalculate TIM2 period for the new settings
 TIM2_Ticks = (uint32_t)((float)TIM2CLK / ((float)sample_buffer_size * output_freq_signal))- 1;
 __HAL_TIM_SET_AUTORELOAD(&htim2, TIM2_Ticks);
 HAL_DMA_Start_IT(&hdma_tim2_ch1, (uint32_t)lut_p[active_lut_id], DestAddress, sample_buffer_size);
 }
 /* USER CODE END 0 */
 /**
 * @brief The application entry point.
 */
 int main(void)
 {
 HAL_Init();
 SystemClock_Config();
 MX_GPIO_Init();
 MX_DMA_Init();
 MX_TIM2_Init();
 MX_TIM3_Init();
 /* USER CODE BEGIN 2 */
 // Safe LCD Initialization Sequence
 HAL_Delay(30);
 lcd_command(POWER_UP);
 lcd_command(FOURBIT_MODE);
 lcd_command(DISPLAY_ON);
 lcd_command(TWOLINE_MODE);
 lcd_command(CLEAR);
 //---Start Sound Generation--
HAL_TIM_PWM_Start(&htim3, TIM_CHANNEL_3);
 HAL_TIM_Base_Start(&htim2);
 // Initial setup for the first waveform (Sine)
 Configure_Audio_Output();
 lcd_putstring((char*)lut_names[active_lut_id]);
 __HAL_TIM_ENABLE_DMA(&htim2, TIM_DMA_CC1);
 /* USER CODE END 2 */
 while (1) {}
 }
